oxy_webhelp_navlinks = {"github_recover-d39536e43216":{"topics":[{"title":"Privilege elevation for GitHub recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> enhances the security of your GitHub organization by employing a         least permission model that limits the access granted to the minimal necessary roles and         resources.<\/p>","href":"github\/github_privilege_elevation.html","attributes":{"data-id":"github_privilege_elevation"},"menu":{"hasChildren":false},"tocID":"github_privilege_elevation-d39536e43230","topics":[]},{"title":"Recovering GitHub repositories","shortdesc":"<p class=\"shortdesc\">Recover GitHub repositories from a protected snapshot.<\/p>","href":"github\/github_recovering_repos.html","attributes":{"data-id":"github_recovering_repos"},"menu":{"hasChildren":false},"tocID":"github_recovering_repos-d39536e43243","topics":[]},{"title":"Recovering GitHub repository with pull requests and issues","shortdesc":"<p class=\"shortdesc\">Recover a GitHub repository together with its pull requests and issues into a new         repository in the same organization.<\/p>","href":"github\/github_recovering_issues_prs.html","attributes":{"data-id":"github_recovering_issues_prs"},"menu":{"hasChildren":false},"tocID":"github_recovering_issues_prs-d39536e43254","topics":[]},{"title":"GitHub repository backup and recovery settings","shortdesc":"<p class=\"shortdesc\">In addition to repository contents, <span class=\"ph\">RSC<\/span> backs up a curated set of         GitHub repository-level settings as part of every repository snapshot and reapplies them to         the destination repository during recovery.<\/p>","href":"github\/github_settings_backup_recovery.html","attributes":{"data-id":"github_settings_backup_recovery"},"menu":{"hasChildren":false},"tocID":"github_settings_backup_recovery-d39536e43265","topics":[]}]}};